use alloy::{
    network::{Ethereum, EthereumWallet, TransactionBuilder},
    primitives::{Address, B256},
    providers::{
        fillers::{FillProvider, JoinFill, WalletFiller},
        utils::JoinedRecommendedFillers,
        Provider, ProviderBuilder, RootProvider,
    },
    signers::{local::PrivateKeySigner, Signature, Signer},
};
use eyre::Context;
use std::sync::{Arc, Weak};
use stylus_tools::devnet::Node;
use tokio::sync::Mutex;

use crate::deploy::Deployer;

const DEFAULT_FUNDING_ETH: &str = "1";

/// An Alloy provider configured with recommended transaction fillers and a local signer.
pub type Wallet = FillProvider<
    JoinFill<JoinedRecommendedFillers, WalletFiller<EthereumWallet>>,
    RootProvider,
    Ethereum,
>;

/// A funded test account on the SDK-managed Nitro devnet.
#[derive(Clone)]
pub struct Account {
    /// This account's local private key wrapper.
    pub signer: PrivateKeySigner,
    /// This account's Alloy provider and signer.
    pub wallet: Wallet,
    rpc_url: String,
    // Keep the SDK-managed devnet alive exactly as long as accounts use it.
    // A process-global strong `Node` never gets dropped, leaving Nitro
    // containers running after test binaries exit.
    _node: Arc<Node>,
}

impl std::fmt::Debug for Account {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Account")
            .field("signer", &self.signer)
            .field("rpc_url", &self.rpc_url)
            .finish_non_exhaustive()
    }
}

impl Account {
    /// Create and fund a fresh account on the shared devnet for this test binary.
    ///
    /// # Errors
    ///
    /// Returns an error if the SDK devnet cannot start or account funding fails.
    pub async fn new() -> eyre::Result<Self> {
        let node = {
            let mut devnet = DEVNET.lock().await;
            if let Some(node) = devnet.upgrade() {
                node
            } else {
                let node = Arc::new(
                    Node::new()
                        .await
                        .wrap_err("failed to start Stylus SDK devnet")?,
                );
                *devnet = Arc::downgrade(&node);
                node
            }
        };
        let signer = PrivateKeySigner::random();
        let address = signer.address();

        // Every test account is funded by the devnet owner. Serialize these transfers so the
        // owner provider's nonce filler cannot race when tests execute concurrently.
        let _guard = FUNDING_LOCK.lock().await;
        let owner = node.create_provider().await?;
        let amount =
            alloy::primitives::utils::parse_ether(DEFAULT_FUNDING_ETH)?;
        owner
            .send_transaction(
                alloy::rpc::types::TransactionRequest::default()
                    .with_to(address)
                    .with_value(amount),
            )
            .await?
            .get_receipt()
            .await?;

        let rpc_url = node.rpc().to_owned();
        let rpc = rpc_url.parse().context("invalid devnet RPC URL")?;
        let wallet = ProviderBuilder::new()
            .wallet(EthereumWallet::from(signer.clone()))
            .connect_http(rpc);

        Ok(Self { signer, wallet, rpc_url, _node: node })
    }

    /// Return the private key as a hexadecimal string.
    #[must_use]
    pub fn pk(&self) -> String {
        alloy::hex::encode(self.signer.to_bytes())
    }

    /// Return this account's address.
    #[must_use]
    pub fn address(&self) -> Address {
        self.signer.address()
    }

    /// Return the endpoint used by this account's provider.
    #[must_use]
    pub fn url(&self) -> &str {
        &self.rpc_url
    }

    /// Sign a hash with this account.
    ///
    /// # Panics
    ///
    /// Panics if the local signer cannot sign the supplied hash.
    pub async fn sign_hash(&self, hash: &B256) -> Signature {
        self.signer
            .sign_hash(hash)
            .await
            .expect("local signer should sign hashes")
    }

    /// Sign a message with this account.
    ///
    /// # Panics
    ///
    /// Panics if the local signer cannot sign the supplied message.
    pub async fn sign_message(&self, message: &[u8]) -> Signature {
        self.signer
            .sign_message(message)
            .await
            .expect("local signer should sign messages")
    }

    /// Create a deployer for this account.
    #[must_use]
    pub fn as_deployer(&self) -> Deployer {
        Deployer::new(self.clone())
    }
}

static DEVNET: Mutex<Weak<Node>> = Mutex::const_new(Weak::new());
static FUNDING_LOCK: Mutex<()> = Mutex::const_new(());
#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR=$(git -C "$(dirname "$(realpath "$0")")" rev-parse --show-toplevel)
cd "$ROOT_DIR"

# Pass a contract directory to resume a long serial run after a failure.
start_at=${1:-}
started=0
found_start=0
if [[ -z "$start_at" ]]; then
  started=1
fi

# Each example is its own Cargo package. Run every package with an integration
# test so SDK devnet tests are not silently skipped by workspace feature selection.
while IFS= read -r -d '' stylus_config; do
  contract_dir=$(dirname "$stylus_config")
  if [[ -n "$start_at" && "$contract_dir" == "$start_at" ]]; then
    started=1
    found_start=1
  fi
  ((started)) || continue

  test_dir="$contract_dir/tests"
  [[ -d "$test_dir" ]] || continue

  test_targets=()
  while IFS= read -r -d '' test_file; do
    test_name=$(basename "$test_file" .rs)
    test_targets+=(--test "$test_name")
  done < <(find "$test_dir" -maxdepth 1 -type f -name '*.rs' -print0 | sort -z)
  ((${#test_targets[@]})) || continue

  echo "Running devnet tests in $contract_dir"
  (
    cd "$contract_dir"
    cargo test --manifest-path "$ROOT_DIR/$contract_dir/Cargo.toml" \
      --features devnet \
      "${test_targets[@]}" -- --test-threads=1
  )
done < <(find examples templates -name Stylus.toml -print0 | sort -z)

if [[ -n "$start_at" && "$found_start" -eq 0 ]]; then
  echo "No Stylus.toml found for $start_at" >&2
  exit 1
fi
#!/bin/bash
set -e

MYDIR=$(realpath "$(dirname "$0")")
cd "$MYDIR"
cd ..

# Optimize contract's wasm binary by crate name.
opt_wasm() {
  local CONTRACT_CRATE_NAME=$1
  local CONTRACT_BIN_NAME="${CONTRACT_CRATE_NAME//-/_}.wasm"
  local CONTRACT_OPT_BIN_NAME="${CONTRACT_CRATE_NAME//-/_}_opt.wasm"

  echo
  echo "Optimizing $CONTRACT_CRATE_NAME WASM binary"
  # https://rustwasm.github.io/book/reference/code-size.html#use-the-wasm-opt-tool
  wasm-opt --enable-bulk-memory -O3 -o ./target/wasm32-unknown-unknown/release/"$CONTRACT_OPT_BIN_NAME" ./target/wasm32-unknown-unknown/release/"$CONTRACT_BIN_NAME"
}

# Retrieve the contract crate names configured for cargo-stylus.
get_example_crate_names() {
  while IFS= read -r manifest; do
    local contract_dir
    contract_dir=$(dirname "$manifest")
    sed -n '/^\[package\]/,/^\[/s/^name = "\(.*\)"/\1/p' "$contract_dir/Cargo.toml"
  done < <(find ./examples ./templates -type f -name Stylus.toml | sort)
}

# The test support, benchmark runner, and basic-script CLI are host tools.
# Build every Stylus contract package for WASM and skip those native packages.
cargo build --workspace \
  --exclude benches \
  --exclude stylus-test-support \
  --exclude basic-script-example \
  --release \
  --target wasm32-unknown-unknown
cargo build \
  --manifest-path templates/crypto-erc20/Cargo.toml \
  --release \
  --target wasm32-unknown-unknown \
  --target-dir target

# Optimize contract's wasm for gas usage.
for CRATE_NAME in $(get_example_crate_names); do
  opt_wasm "$CRATE_NAME"
done

# No need to compile benchmarks with `--release`
# since this only runs the benchmarking code and the contracts have already been compiled with `--release`.
# The benchmark helper starts its SDK-managed Nitro devnet automatically.
cargo run -p benches
echo "This benchmarks measure gas execution cost,
 the 21000 EVM base gas fee is omitted."
echo
echo "To measure non cached contract's gas usage correctly,
 benchmarks should run on a clean instance of the nitro test node."
echo
echo "Finished running benches!"
