    72	mod tests {
    73	    #![allow(clippy::unused_self)]
    74	
    75	    use alloy_primitives::{uint, Address, U256};
    76	    use stylus_sdk::storage::StorageAddress;
    77	    use stylus_sdk::testing::TestVM;
    78	
    79	    use super::*;
    80	
    81	    const IMPLEMENTATION_SLOT: U256 = uint!(12345_U256);
    82	
    83	    #[storage]
    84	    #[entrypoint]
    85	    pub struct Erc1967 {
    86	        address: StorageAddress,
    87	    }
    88	
    89	    #[public]
    90	    impl Erc1967 {
    91	        fn get_implementation(&self) -> Address {
    92	            StorageSlot::get_slot::<StorageAddress>(self, IMPLEMENTATION_SLOT)
    93	                .get()
    94	        }
    95	
    96	        fn set_implementation(&self, new_implementation: Address) {
    97	            StorageSlot::get_slot::<StorageAddress>(self, IMPLEMENTATION_SLOT)
    98	                .set(new_implementation);
    99	        }
