    80	/// Build a constructor descriptor using the ABI type information from Stylus SDK values.
    81	#[macro_export]
    82	macro_rules! constructor {
    83	    () => {{
    84	        $crate::Constructor {
    85	            signature: "constructor()".to_string(),
    86	            args: vec![],
    87	        }
    88	    }};
    89	    ($first:expr $(, $rest:expr)* $(,)?) => {{
    90	        fn get_abi_str<T: stylus_sdk::abi::AbiType>(_: T) -> &'static str {
    91	            <T as stylus_sdk::abi::AbiType>::ABI.as_str()
    92	        }
    93	
    94	        let signature_params = {
    95	            let mut params = vec![get_abi_str($first)];
    96	            $(params.push(get_abi_str($rest));)*
    97	            params.join(",")
    98	        };
    99	        let args = vec![
   100	            $crate::AbiTypeToString::abi_type_to_string(&$first)
   101	            $(, $crate::AbiTypeToString::abi_type_to_string(&$rest))*
   102	        ];
   103	        $crate::Constructor {
   104	            signature: format!("constructor({signature_params})"),
   105	            args,
   106	        }
   107	    }};
   108	}
