   219	/// Check a workspace contract through the SDK pipeline, with an extra WAT
   220	/// round trip after optional optimization for the pinned Nitro devnet parser.
   221	async fn check_contract_for_devnet(
   222	    contract: &Contract,
   223	    config: &DeploymentConfig,
   224	    provider: &impl Provider,
